    {
      "id": 1,
      "claim": "Common‑law assault requires (a) intent to cause another to reasonably apprehend imminent harmful or offensive contact, and (b) an act that creates that apprehension.",
      "evidence": "Standard criminal law definition of assault.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The friend intentionally jumped out, brandished a toy pistol, and seized the necklace, causing the woman to become hysterical and plead for her life.",
      "evidence": "Fact pattern describing the friend’s conduct and the woman’s reaction.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The woman’s fear of death was a reasonable apprehension of imminent harmful contact, satisfying element (b) of assault.",
      "evidence": "A reasonable person would fear deadly force when a gun (even a toy) is pointed at them.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Thus all elements of assault are met; the friend is guilty of assault.",
      "evidence": "Logical combination of steps 1‑3.",
      "weight": 0.10,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Robbery requires (a) taking personal property, (b) by force or intimidation, and (c) intent to permanently deprive the owner.",
      "evidence": "Standard definition of robbery.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 6,
      "claim": "The friend lacked intent to permanently deprive because she immediately returned the necklace and explained the act was a joke.",
      "evidence": "Fact pattern: “handed the necklace back… ‘I just wanted to frighten you.’”",
      "weight": 0.07,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "Therefore robbery is not satisfied.",
      "evidence": "Missing element (c) from step 6.",
      "weight": 0.03,
      "depends_on": [5, 6]
    },
    {
      "id": 8,
      "claim": "Battery requires intentional harmful or offensive contact with the person; although the friend touched the victim’s neck, the contact was incidental to the threat and the gravamen of the conduct is intimidation, making assault the better charge.",
      "evidence": "Criminal law principle that when a single act satisfies both assault and battery, the offense that captures the primary wrongful intent (here, intimidation) is preferred.",
      "weight": 0.05,
      "depends_on": [1, 2]
    }
